package main;

import constants.Constants;
import constants.Message;
import constants.SalaryStatus;
import controller.WorkerController;
import dto.WorkerRequestDTO;
import java.util.Scanner;
import utils.Validation;

/**
 * Diem bat dau: menu, ban phim (Scanner chi o day), kiem du lieu qua Validation, goi
 * Controller dung 1 lan cho moi lua chon. Loi cua moi tang deu bat va in o day.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Constructor private: Main chi co ham static (checklist 3.4)
    private Main() {
    }

    // Chay chuong trinh: lap menu den khi chon 5
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        WorkerController workerController = new WorkerController();
        boolean running = true;
        int choice = 0;

        // Hien lai menu sau moi chuc nang, den khi chon thoat
        while (running) {
            System.out.println(Message.MENU);
            choice = inputChoice(sc);

            // Loi tu kho/service (ma trung, ma khong co, giam qua luong) in o catch
            try {
                // Moi lua chon goi controller dung 1 lan
                switch (choice) {
                    // 1: nhap 5 o roi them cong nhan
                    case Constants.MENU_ADD:
                        workerController.addWorker(inputWorker(sc));
                        break;

                    // 2: nhap ma + so tien roi tang luong
                    case Constants.MENU_UP:
                        workerController.changeSalary(inputSalaryChange(sc, SalaryStatus.UP));
                        break;

                    // 3: nhap ma + so tien roi giam luong
                    case Constants.MENU_DOWN:
                        workerController.changeSalary(inputSalaryChange(sc, SalaryStatus.DOWN));
                        break;

                    // 4: in bang lich su luong
                    case Constants.MENU_DISPLAY:
                        System.out.println(Message.TITLE_DISPLAY);
                        workerController.displaySalaryHistory();
                        break;

                    // 5: dung vong lap
                    case Constants.MENU_EXIT:
                        running = false;
                        System.out.println(Message.GOODBYE);
                        break;

                    // Khong xay ra: inputChoice chi tra 1..5
                    default:
                        break;
                }
            } catch (Exception e) {
                // Cau loi da viet san o Message, nem tu kho hoac service
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi lua chon menu den khi la so tu 1 den 5
    private static int inputChoice(Scanner sc) {
        // Lap den khi Validation chap nhan
        while (true) {
            System.out.print(Message.INPUT_CHOICE);

            // Sai thi in ly do roi hoi lai
            try {
                return Validation.getChoice(sc.nextLine(), Constants.MENU_MIN,
                        Constants.MENU_EXIT);
            } catch (Exception e) {
                // Go chu hoac ngoai 1..5
                System.out.println(e.getMessage());
            }
        }
    }

    // Chuc nang 1: tieu de roi 5 o, o nao sai thi hoi lai o do
    private static WorkerRequestDTO inputWorker(Scanner sc) {
        WorkerRequestDTO workerRequestDTO = new WorkerRequestDTO();

        System.out.println(Message.TITLE_ADD);
        workerRequestDTO.setCode(inputCode(sc));
        workerRequestDTO.setName(inputName(sc));
        workerRequestDTO.setAge(inputAge(sc));
        workerRequestDTO.setSalary(inputSalary(sc));
        workerRequestDTO.setWorkLocation(inputLocation(sc));
        return workerRequestDTO;
