/**
 * Ham dinh dang dung chung: in so tien giong de bai (1100, 999.5) tren moi may.
 *
 * @author CuongThai Academy
 */
public final class FormatUtils {

    // Constructor private: lop chi co ham static
    private FormatUtils() {
    }

    // Doi so tien thanh chu: so tron khong co .0; Locale.US de may tieng Viet khong in 999,5
    public static String formatMoney(double money) {
